{"path": "scale_generator.py", "content": "SHARPS = ["A", "A#", "B", "C", "C#", "D", "D#", "E", "F", "F#", "G", "G#"]
FLATS = ["A", "Bb", "B", "C", "Db", "D", "Eb", "E", "F", "Gb", "G", "Ab"]

FLAT_TONICS = {"F", "Bb", "Eb", "Ab", "Db", "Gb", "d", "g", "c", "f", "bb", "eb"}

STEPS = {"m": 1, "M": 2, "A": 3}


class Scale:
    def __init__(self, tonic):
        self.notes = FLATS if tonic in FLAT_TONICS else SHARPS
        normalized = tonic[0].upper() + tonic[1:]
        if normalized in self.notes:
            self.start = self.notes.index(normalized)
        else:
            other = SHARPS if self.notes is FLATS else FLATS
            self.start = other.index(normalized)

    def chromatic(self):
        return self.notes[self.start:] + self.notes[:self.start]

    def interval(self, intervals):
        index = self.start
        result = [self.notes[index]]
        for step in intervals:
            index = (index + STEPS[step]) % 12
            result.append(self.notes[index])
        return result
